// MARK: - Tipitaka Tree Building

public struct Tipitaka {
  /// Prevent instantiation - Tipitaka is a namespace for static functions only
  private init() {}

  /// Constructs a nested tree from a flat list of refs with paths
  ///
  /// Parses paths to determine parent-child relationships and organizes
  /// refs into a tree suitable for OutlineGroup rendering.
  ///
  /// - Parameter flatRefs: Flat array of refs from db-manifest
  /// - Returns: Array of root-level refs with nested children
  public static func buildTree(from flatRefs: [TipitakaRef]) -> [TipitakaRef] {
    var refsByPath: [String: TipitakaRef] = [:]

    // Index all refs by path
    for ref in flatRefs {
      refsByPath[ref.id] = ref
    }

    // Build parent-child relationships bottom-up
    // Sort by path length (deepest first) so children are built before parents
    let sortedPaths = refsByPath.keys.sorted { path1, path2 in
      path1.split(separator: "/").count > path2.split(separator: "/").count
    }

    for path in sortedPaths {
      guard var ref = refsByPath[path] else { continue }
      let segments = path.split(separator: "/", omittingEmptySubsequences: true)

      // Find all direct children (paths with exactly one more segment)
      let children = refsByPath.values.filter { candidate in
        let candidateSegments = candidate.id.split(
          separator: "/",
          omittingEmptySubsequences: true,
        )
        return candidateSegments.count == segments.count + 1 &&
          candidate.id.hasPrefix(path + "/")
      }

      if !children.isEmpty {
        ref.children = children.sorted { $0.id < $1.id }
        refsByPath[path] = ref
      }
    }

    // Return root level only (depth 1, like "/sutta", "/vinaya")
    return refsByPath.values
      .filter {
        $0.id.split(separator: "/", omittingEmptySubsequences: true).count == 1
      }
      .sorted { $0.id < $1.id }
  }

  /// Searches for a ref by its path ID in the tree
  ///
  /// - Parameters:
  ///   - id: Path to search for (e.g., "/sutta/sn/sn1")
  ///   - forest: Root-level refs to search within
  /// - Returns: The matching ref, or nil if not found
  public static func findRef(byId id: String,
                             in forest: [TipitakaRef]) -> TipitakaRef?
  {
    for ref in forest {
      if ref.id == id {
        return ref
      }
      if let children = ref.children,
         let found = findRef(byId: id, in: children)
      {
        return found
      }
    }
    return nil
  }

  /// Returns parent directory path for a suttaUid in canonical Tipitaka
  /// structure
  ///
  /// Maps suttaUid (e.g., "an1.3", "dn14", "sn1.1") to its parent directory
  /// path
  /// in the canonical Pali structure (local/ebt-data/root/pli/ms). The mapping
  /// is
  /// invariant across all language/author translations.
  ///
  /// Example:
  /// - "an1.3" → "/sutta/an/an1"
  /// - "dn14" → "/sutta/dn"
  /// - "sn1.5" → "/sutta/sn/sn1"
  ///
  /// - Parameter suttaUid: Sutta identifier (e.g., "an1.3", "dn14")
  /// - Returns: Parent directory path, or nil if suttaUid not found
  public static func parentPath(suttaUid: String) -> String? {
    // Extract prefix (letters only, up to first digit or dot)
    let prefix = suttaUid.prefix { $0.isLetter }.lowercased()

    // Extract numeric part (e.g., "1" from "an1", "14" from "dn14")
    let numericStart = suttaUid.firstIndex { $0.isNumber }
    guard let numStart = numericStart else { return nil }

    let numericPart = suttaUid[numStart...]
    let numberStr = String(numericPart.prefix { $0.isNumber })
    guard let number = Int(numberStr) else { return nil }

    // Build key to lookup
    let lookupKey = prefix + numberStr

    return suttaUidToPaths[lookupKey]
  }

  /// Builds complete Tipiṭaka tree for language/author combination
  ///
  /// Queries database for available suttaUids, then creates hierarchy by
  /// looking up
  /// their canonical paths. Always returns synthetic root, even if no suttas
  /// available.
  ///
  /// - Parameters:
  ///   - lang: Language code (e.g., "en", "de", "pli")
  ///   - author: Author/translator (e.g., "soma", "sujato")
  /// - Returns: Root TipitakaRef containing all sections
  public static func authorTipitaka(lang: String,
                                    author: String) async -> TipitakaRef
  {
    // Query EbtData for available suttaUids
    var suttaUids = await EbtData.shared.suttaUidsForAuthor(
      lang: lang,
      author: author,
    )

    // Sort suttaUids using proper Sutta Central ordering
    suttaUids.sort { SuttaCentralId.compareLow($0, $1) < 0 }

    // Collect all unique paths from suttaUids, plus leaf nodes for each
    // suttaUid
    // Using array to preserve sorted order, pathSet for O(1) duplicate checking
    var pathsToInclude: [String] = []
    var pathSet: Set<String> = []
    var pathToSuttaUid: [String: String] =
      [:] // Map leaf paths to suttaUids for abbreviations
    for suttaUid in suttaUids {
      if let parentPath = parentPath(suttaUid: suttaUid) {
        // Add parent path
        if !pathSet.contains(parentPath) {
          pathsToInclude.append(parentPath)
          pathSet.insert(parentPath)
        }
        // Add leaf node for this suttaUid
        let leafPath = parentPath + "/" + suttaUid
        if !pathSet.contains(leafPath) {
          pathsToInclude.append(leafPath)
          pathSet.insert(leafPath)
          pathToSuttaUid[leafPath] = suttaUid // Record suttaUid for this leaf
        }
      }
    }

    // Build flat list of all nodes that should exist
    // Using array to preserve order, allPathsSet for O(1) duplicate checking
    var allPaths: [String] = []
    var allPathsSet: Set<String> = []
    for path in pathsToInclude {
      // Add the path itself
      if !allPathsSet.contains(path) {
        allPaths.append(path)
        allPathsSet.insert(path)
      }
      // Add all parent paths
      var current = path
      while !current.isEmpty, current != "/" {
        let parent = (current as NSString).deletingLastPathComponent
        if parent.isEmpty || parent == "/" {
          break
        }
        if !allPathsSet.contains(parent) {
          allPaths.append(parent)
          allPathsSet.insert(parent)
        }
        current = parent
      }
    }

    // Create TipitakaRef nodes for each path
    var nodesByPath: [String: TipitakaRef] = [:]
    for path in allPaths {
      // For leaf nodes (suttaUids), use abbreviation followed by Pali document
      // name; otherwise use path component
      let name: String
      let caption: String
      if let suttaUid = pathToSuttaUid[path],
         let suttaRef = SuttaRef.create(suttaUid)
      {
        name = suttaRef.abbreviation()
        caption = Tipitaka.tipitakaName(suttaRef: suttaRef)
      } else {
        let pathPart = (path as NSString).lastPathComponent
        name = Tipitaka.tipitakaName(id: pathPart)
        caption = ""
      }
      nodesByPath[path] = TipitakaRef(id: path, name: name, caption: caption)
    }

    // Build parent-child relationships (similar to buildTree)
    // Sort by path depth (deepest first) so children are built before parents
    let sortedPaths = allPaths.sorted { path1, path2 in
      path1.split(separator: "/").count > path2.split(separator: "/").count
    }

    for path in sortedPaths {
      guard var node = nodesByPath[path] else { continue }
      let pathSegments = path.split(
        separator: "/",
        omittingEmptySubsequences: true,
      )

      // Find all direct children in the order they appear in pathsToInclude
      // This preserves the sorted order from suttaUids without re-sorting
      var children: [TipitakaRef] = []
      for candidatePath in pathsToInclude {
        if let candidate = nodesByPath[candidatePath] {
          let candidateSegments = candidate.id.split(
            separator: "/",
            omittingEmptySubsequences: true,
          )
          if candidateSegments.count == pathSegments.count + 1,
             candidate.id.hasPrefix(path + "/")
          {
            children.append(candidate)
          }
        }
      }

      if !children.isEmpty {
        node.children = children
        nodesByPath[path] = node
      }
    }

    // Build root-level nodes (children of synthetic root)
    var rootChildren: [TipitakaRef] = []
    for section in ["/sutta", "/vinaya", "/abhidhamma"] {
      if let sectionNode = nodesByPath[section] {
        var node = sectionNode
        // Collect children of this section
        let childPaths = allPaths.filter { path in
          let parent = (path as NSString).deletingLastPathComponent
          return parent == section
        }
        if !childPaths.isEmpty {
          node.children = childPaths.compactMap { nodesByPath[$0] }
        }
        rootChildren.append(node)
      } else if pathsToInclude.contains { $0.hasPrefix(section + "/") } {
        // Create placeholder section if it has children but doesn't exist in
        // nodesByPath
        var sectionNode = TipitakaRef(
          id: section,
          name: section == "/sutta" ? "Sutta Piṭaka" :
            section == "/vinaya" ? "Vinaya Piṭaka" :
            "Abhidhamma Piṭaka",
        )
        let childPaths = allPaths.filter { path in
          let parent = (path as NSString).deletingLastPathComponent
          return parent == section
        }
        if !childPaths.isEmpty {
          sectionNode.children = childPaths.compactMap { nodesByPath[$0] }
        }
        rootChildren.append(sectionNode)
      }
    }

    // Create synthetic root with sections as children
    return TipitakaRef(
      id: "/tipitaka",
      name: "Tipiṭaka",
      caption: "Buddhist Canon",
      children: rootChildren.sorted { $0.id < $1.id },
    )
  }

  /// Returns the Pali document name (segment 0.3) for a sutta
  /// - Parameter suttaRef: SuttaRef to look up
  /// - Returns: Pali document name, or the suttaUid if not found
  public static func tipitakaName(suttaRef: SuttaRef) -> String {
    paliDocumentNameMapping[suttaRef.suttaUid] ?? suttaRef.suttaUid
  }

  public static func tipitakaName(id: String) -> String {
    SuttaCentralUid.nameMapping[id] ?? SuttaCentralUid.abbrMapping[id] ?? id
  }
}
